from pathlib import Path
from html import escape
import hashlib
import json
import re
from design_status import with_design_notice

HERE = Path(__file__).resolve().parent
DATA = HERE / '威力体系设计草案.json'
d = json.loads(DATA.read_text(encoding='utf-8'))
e = escape

def paragraphs(items):
    return ''.join(f'<p>{e(x)}</p>' for x in items)

def bullets(items):
    return '<ul>' + ''.join(f'<li>{e(x)}</li>' for x in items) + '</ul>'

def card_row(c):
    first = ('旧稿：首批7张' if c['first_wave'] else '旧稿：后续4张') if d.get('review_status') == 'needs_redesign' else ('首批打样' if c['first_wave'] else '第二批扩展')
    search = e(' '.join(str(c[k]) for k in ('name','role','text','rarity')), quote=True)
    return f'''<article class="card-row" data-first="{str(c['first_wave']).lower()}" data-search="{search}">
      <div class="card-title"><span class="cost" aria-label="费用{c['cost']}">{c['cost']}</span><div><h3>{e(c['name'])}</h3><span class="meta">{e(c['rarity'])} · {e(c['type'])} · {e(c['role'])}</span><br><span class="phase">{first}</span></div></div>
      <div class="card-text"><p>{e(c['text'])}</p><p class="upgrade">升级：{e(c['upgrade'])}</p></div>
      <div class="card-reason"><p>{e(c['reason'])}</p><details><summary>规则与取舍</summary><p>{e(c['note'])}</p></details></div></article>'''

mapping = ''.join(f'<tr><th scope="row">{e(x["role"])}<small>{e(x["reference"])}</small></th><td>{e(x["verified"])}</td><td>{e(x["design"])}</td></tr>' for x in d['strength_mapping'])
rules = ''.join(f'<div class="rule-row"><h3>{e(x["term"])}</h3><p>{e(x["text"])}</p></div>' for x in d['rules'])
builds = ''.join(f'<article class="build"><span class="eyebrow">倾向 {i:02d}</span><h3>{e(x["name"])}</h3><p class="picks">{e(x["picks"])}</p><p>{e(x["play"])}</p><p>{e(x["choice"])}</p><p class="weakness">代价：{e(x["weakness"])}</p></article>' for i,x in enumerate(d['builds'],1))
examples = ''.join(f'<details class="example" {"open" if i==0 else ""}><summary>{e(x["name"])}</summary><p class="muted">{e(x["setup"])}</p><ol>'+''.join(f'<li>{e(s)}</li>' for s in x['steps'])+f'</ol><p class="result">{e(x["result"])}</p></details>' for i,x in enumerate(d['examples']))
review = ''.join(f'<li><b>{e(x["issue"])}</b><p>{e(x["resolution"])}</p></li>' for x in d['review'])
source_files = sorted({p for item in d['strength_mapping'] for p in item['files']})
source_records = []
for rel in source_files:
    path = Path(d['source_root']) / rel
    source_records.append({'path': path.as_posix(), 'sha256': hashlib.sha256(path.read_bytes()).hexdigest()})
evidence = {'version':d['source_version'], 'files':source_records, 'mapping':d['strength_mapping']}
(HERE / '威力体系力量参考.json').write_text(json.dumps(evidence,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')

